def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    counts = np.floor_divide(remaining, item, where=remaining >= 0)
    return np.where(remaining >= 0, counts, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_fill_ratio = 0.8
    target_capacity = bins * target_fill_ratio
    deviation = np.abs(remaining - target_capacity)
    return np.where(remaining >= 0, -deviation, -np.inf)
